<?php $title='Checkout';require 'includes/header.php';if(!logged())redirect('auth/login.php');$s=$pdo->prepare('SELECT c.quantity,p.* FROM cart_items c JOIN products p ON p.id=c.product_id WHERE c.user_id=?');$s->execute([$_SESSION['user']['id']]);$items=$s->fetchAll();$total=array_sum(array_map(fn($x)=>$x['price']*$x['quantity'],$items));if(!$items){redirect('cart.php');}if($_SERVER['REQUEST_METHOD']==='POST'){$addr=trim($_POST['address']);$pdo->beginTransaction();$o=$pdo->prepare('INSERT INTO orders(user_id,total,address) VALUES(?,?,?)');$o->execute([$_SESSION['user']['id'],$total,$addr]);$oid=$pdo->lastInsertId();$oi=$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,price) VALUES(?,?,?,?)');foreach($items as $x){$oi->execute([$oid,$x['id'],$x['quantity'],$x['price']]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$x['quantity'],$x['id']]);}$pdo->prepare('DELETE FROM cart_items WHERE user_id=?')->execute([$_SESSION['user']['id']]);$pdo->commit();flash('Order #'.$oid.' placed successfully!');redirect('orders.php');} ?><section class="container section"><div class="checkout"><div><span class="eyebrow">SECURE CHECKOUT</span><h1>Delivery details</h1><form method="post"><label>Delivery address<textarea name="address" rows="5" required placeholder="House no, street, city, pincode"></textarea></label><label>Payment method<select><option>Cash on Delivery</option><option>UPI (Demo)</option><option>Card (Demo)</option></select></label><button class="btn primary full">Place order · ₹<?=number_format($total)?></button></form></div><aside class="summary"><h2>Items</h2><?php foreach($items as $x):?><div><span><?=e($x['name'])?> × <?=$x['quantity']?></span><b>₹<?=number_format($x['price']*$x['quantity'])?></b></div><?php endforeach;?><hr><div class="grand"><span>Total</span><b>₹<?=number_format($total)?></b></div></aside></div></section><?php require 'includes/footer.php'; ?>